-- Room createAllTables from custom 4.0.17 (06232530), one statement per line.
CREATE TABLE IF NOT EXISTS `sessions` (`id` TEXT NOT NULL, `title` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `totalInputTokens` INTEGER NOT NULL, `totalOutputTokens` INTEGER NOT NULL, `totalCachedTokens` INTEGER NOT NULL, `totalCacheWriteTokens` INTEGER NOT NULL, `requestCount` INTEGER NOT NULL, `lastInputTokens` INTEGER NOT NULL, `projectId` TEXT, `compactionSummary` TEXT NOT NULL, `compactionBefore` INTEGER NOT NULL, `pendingPlan` TEXT, `modelSelectionJson` TEXT, `workspaceSelectionJson` TEXT, `conversationJson` TEXT, `workProjectId` TEXT, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `messages` (`id` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `role` TEXT NOT NULL, `text` TEXT NOT NULL, `toolCallsJson` TEXT NOT NULL, `toolCallId` TEXT, `toolName` TEXT, `isError` INTEGER NOT NULL, `thinking` TEXT NOT NULL, `thinkingMs` INTEGER NOT NULL, `outputTokens` INTEGER NOT NULL, `generationMs` INTEGER NOT NULL, `firstTokenMs` INTEGER NOT NULL, `streamMs` INTEGER NOT NULL, `imagesJson` TEXT NOT NULL, `turnId` TEXT, `createdAt` INTEGER NOT NULL, `artifactJson` TEXT, `generationJson` TEXT, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_messages_sessionId` ON `messages` (`sessionId`)
CREATE TABLE IF NOT EXISTS `projects` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `kind` TEXT NOT NULL, `uri` TEXT, `lastUsedAt` INTEGER NOT NULL, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `work_projects` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `selectionJson` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `chatNamePattern` TEXT, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `checkpoints` (`id` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `turnId` TEXT NOT NULL, `relPath` TEXT NOT NULL, `contentB64` TEXT NOT NULL, `existedBefore` INTEGER NOT NULL, `wasDirectory` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_checkpoints_sessionId` ON `checkpoints` (`sessionId`)
CREATE TABLE IF NOT EXISTS `snippets` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `body` TEXT NOT NULL, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `usage_events` (`rowId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sessionId` TEXT NOT NULL, `providerName` TEXT NOT NULL, `model` TEXT NOT NULL, `inputTokens` INTEGER NOT NULL, `outputTokens` INTEGER NOT NULL, `cachedTokens` INTEGER NOT NULL, `cacheWriteTokens` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `turnId` TEXT, `cacheReported` INTEGER NOT NULL DEFAULT 0, `inputPrice` REAL, `cacheReadPrice` REAL, `cacheWritePrice` REAL)
CREATE INDEX IF NOT EXISTS `index_usage_events_sessionId` ON `usage_events` (`sessionId`)
CREATE TABLE IF NOT EXISTS `file_edits` (`rowId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sessionId` TEXT NOT NULL, `turnId` TEXT NOT NULL, `relPath` TEXT NOT NULL, `added` INTEGER NOT NULL, `removed` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL)
CREATE INDEX IF NOT EXISTS `index_file_edits_sessionId` ON `file_edits` (`sessionId`)
CREATE INDEX IF NOT EXISTS `index_file_edits_turnId` ON `file_edits` (`turnId`)
CREATE TABLE IF NOT EXISTS `code_activity` (`id` TEXT NOT NULL, `fileKey` TEXT NOT NULL, `added` INTEGER NOT NULL, `removed` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_code_activity_createdAt` ON `code_activity` (`createdAt`)
CREATE TABLE IF NOT EXISTS `session_file_changes` (`sessionId` TEXT NOT NULL, `relPath` TEXT NOT NULL, `added` INTEGER NOT NULL, `removed` INTEGER NOT NULL, `isNew` INTEGER NOT NULL, `isDeleted` INTEGER NOT NULL, `baseGzip` BLOB, `hasBase` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`sessionId`, `relPath`))
CREATE INDEX IF NOT EXISTS `index_session_file_changes_updatedAt` ON `session_file_changes` (`updatedAt`)
CREATE VIRTUAL TABLE IF NOT EXISTS `message_fts` USING FTS4(`text` TEXT NOT NULL, tokenize=unicode61, content=`messages`)
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_message_fts_BEFORE_UPDATE BEFORE UPDATE ON `messages` BEGIN DELETE FROM `message_fts` WHERE `docid`=OLD.`rowid`; END
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_message_fts_BEFORE_DELETE BEFORE DELETE ON `messages` BEGIN DELETE FROM `message_fts` WHERE `docid`=OLD.`rowid`; END
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_message_fts_AFTER_UPDATE AFTER UPDATE ON `messages` BEGIN INSERT INTO `message_fts`(`docid`, `text`) VALUES (NEW.`rowid`, NEW.`text`); END
CREATE TRIGGER IF NOT EXISTS room_fts_content_sync_message_fts_AFTER_INSERT AFTER INSERT ON `messages` BEGIN INSERT INTO `message_fts`(`docid`, `text`) VALUES (NEW.`rowid`, NEW.`text`); END
CREATE TABLE IF NOT EXISTS `memories` (`id` TEXT NOT NULL, `text` TEXT NOT NULL, `category` TEXT NOT NULL, `scope` TEXT NOT NULL, `projectId` TEXT, `sourceSessionId` TEXT, `pinned` INTEGER NOT NULL, `enabled` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `lastUsedAt` INTEGER NOT NULL, `useCount` INTEGER NOT NULL, `section` TEXT NOT NULL DEFAULT 'SHARED', `consolidatedInto` TEXT, `isSummary` INTEGER NOT NULL DEFAULT 0, `agentId` TEXT, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_memories_scope` ON `memories` (`scope`)
CREATE INDEX IF NOT EXISTS `index_memories_projectId` ON `memories` (`projectId`)
CREATE INDEX IF NOT EXISTS `index_memories_enabled` ON `memories` (`enabled`)
CREATE TABLE IF NOT EXISTS `chat_answer_versions` (`id` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `groupKey` TEXT NOT NULL, `messagesJson` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_chat_answer_versions_sessionId` ON `chat_answer_versions` (`sessionId`)
CREATE TABLE IF NOT EXISTS `saved_answers` (`messageId` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `text` TEXT NOT NULL, `answeredAt` INTEGER NOT NULL, `savedAt` INTEGER NOT NULL, PRIMARY KEY(`messageId`))
CREATE INDEX IF NOT EXISTS `index_saved_answers_sessionId` ON `saved_answers` (`sessionId`)
CREATE INDEX IF NOT EXISTS `index_saved_answers_savedAt` ON `saved_answers` (`savedAt`)
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT)
INSERT OR REPLACE INTO room_master_table (id,identity_hash) VALUES(42, '5b3452dfd83c5637c7f199c07f93133a')
